import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Insecure ADIDNS","description":"","frontmatter":{"grammarly":false,"search":{"exclude":true}},"headers":[],"relativePath":"d/ad/insecure-adidns.md","filePath":"d/ad/insecure-adidns.md","lastUpdated":1781102819000}`),a={name:`d/ad/insecure-adidns.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/ad/insecure-adidns.md for this page in Markdown format</div><h1 id="insecure-adidns" tabindex="-1">Insecure ADIDNS <a class="header-anchor" href="#insecure-adidns" aria-label="Permalink to “Insecure ADIDNS”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>Domain controller DNS can store its zone data in Active Directory Domain Services (AD DS). There is no need for a separate DNS replication topology like DNS zone transfers. Any domain controller in a domain running the DNS server service can update the DNS zones built into Active Directory. All zone data is automatically replicated by Active Directory replication with domain controllers.</p><p>ADIDNS zones can be modified remotely via dynamic updates or by using LDAP. DNS Dynamic Update Protocol is a DNS-specific protocol designed for updating DNS zones. In Active Directory, dynamic updates are mainly used by computer accounts to add and update their own DNS records. New records can be added to the zone if they do not already exist. Accounts that create new records are given full control over them. User accounts cannot edit existing records or add another record with the same name by default, even if the record type is different (A, AAAA, CNAME, MX, etc.).</p><p>By default, ADIDNS zone access permissions allow regular domain users to create new DNS records that do not yet exist. If zones are configured for insecure dynamic updates, unauthenticated users can modify all existing DNS records. Attackers can exploit both circumstances to get into a MitM position.</p><p>For example, an attacker could add a new record to a DNS zone when a client on the network resolves a name via Link-Local Multicast Name Resolution (LLMNR) or NetBIOS Name Service (NBT-NS). A name that is resolved via LLMNR or NBT-NS typically does not exist in DNS. Alternatively, if DNS zones are configured for insecure dynamic updates, an attacker can modify existing DNS records. This allows an attacker to ensure that clients resolve a specific name using DNS with an arbitrary IP address. If an attacker is in this position, network traffic between two systems can be routed through a system controlled by the attacker, as in any other spoofing attack. In a successful attack, an attacker could obtain credentials to remotely execute code on a Windows machine or move laterally on the network.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><ul><li>Restrict DNS zone access permissions to prevent authenticated users from creating new DNS records.</li><li>Ensure that only secure dynamic DNS updates are allowed.</li><li>Use a dedicated user account for dynamic DNS updates via DHCP.</li><li>Create a wildcard (<code>*</code>), as well as a <code>wpad</code> record (e.g. as a TXT record) in all zones.</li><li>Mail clients should not load images by default, at least from external senders.</li></ul>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};